string category = Tama.Args.Get(args, "category", "OST_Doors");
BuiltInCategory bic;
if (!Enum.TryParse(category, out bic)) throw new InvalidOperationException("Unknown category " + category);
var count = new FilteredElementCollector(doc).OfCategory(bic).WhereElementIsNotElementType().GetElementCount();
var levels = new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().Select(l => l.Name).ToList();
var sheets = new FilteredElementCollector(doc).OfClass(typeof(ViewSheet)).GetElementCount();
var rooms = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_Rooms).WhereElementIsNotElementType().GetElementCount();
return new { category, count, levels, sheets, rooms };
